// main.js —— 入口与主游戏循环
// 职责：创建渲染器/场景/相机、管理 PointerLock、驱动每帧 update、
//        回合流程（波次刷怪 → 全清 → 下一波 → 通关/阵亡结算）
// 经典脚本（非 ES Module）：THREE / CONFIG / GameMap / Player / WeaponSystem /
//        Enemy / PickupSystem / HUD / AudioFX 均由前置脚本挂到 window 提供

class Game {
  constructor() {
    this.hud = new HUD();
    this.audio = new AudioFX();
    this.hud.audio = this.audio;

    // Three 基础设施
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    // 像素比上限：触屏设备 1.5（高 DPR 手机像素压力最大，降级显著提帧率），桌面 2
    const isTouch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, isTouch ? 1.5 : 2));
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    document.body.appendChild(this.renderer.domElement);

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(CONFIG.fov, window.innerWidth / window.innerHeight, 0.05, CONFIG.renderDistance);
    this.scene.add(this.camera);

    // 地图
    this.gameMap = new GameMap(this.scene);

    // 玩家
    this.player = new Player(this.camera, this.gameMap, this.hud);

    // 敌人数组（动态引用，weapon 通过此数组找目标）
    this.enemies = [];

    // 武器系统（依赖 enemies 引用）
    this.weapons = new WeaponSystem(this.scene, this.camera, this.player, this.gameMap, this.enemies, this.hud, this.audio);

    // 血包拾取系统
    this.pickups = new PickupSystem(this.scene, this.gameMap, this.player, this.hud, this.audio);

    // 小地图数据源（必须在 gameMap/player/enemies 都创建完后）
    this.hud.setMinimapRefs(
      this.gameMap,
      this.player,
      () => this.enemies,
      () => this.pickups ? this.pickups.pickups : []
    );

    // 游戏状态
    this.state = 'menu';   // menu / playing / paused / over
    this.wave = 0;
    this.kills = 0;
    this.totalKills = 0;
    this.startTime = 0;
    this.spawnQueue = [];
    this.spawnTimer = 0;

    // 半自动射击：监听鼠标按下（pointerlock 内）
    this._bindUI();
    this._bindResize();

    // 启动渲染循环（始终运行，菜单态也渲染场景）
    this._lastTime = performance.now();
    this._loop();
  }

  // ---------- UI 绑定 ----------
  _bindUI() {
    document.getElementById('startBtn').addEventListener('click', () => this._beginRun());
    document.getElementById('restartBtn').addEventListener('click', () => {
      this.hud.hideResult();
      this._beginRun();
    });
    document.getElementById('resumeBtn').addEventListener('click', () => this._resume());

    // PointerLock
    this._onPointerLockChange = () => {
      if (document.pointerLockElement === this.renderer.domElement) {
        // 锁定中
        if (this.state === 'paused') this.state = 'playing';
        this.hud.hideClickHint();
      } else {
        // 解锁
        if (this.state === 'playing') {
          this.state = 'paused';
          this.hud.showPause();
        }
      }
    };
    document.addEventListener('pointerlockchange', this._onPointerLockChange);

    // 鼠标移动 → 玩家视角
    this._onMouseMove = (e) => {
      if (this.state === 'playing') this.player.onMouseMove(e);
    };
    document.addEventListener('mousemove', this._onMouseMove);

    // 鼠标按下：半自动武器触发一次 + 锁定
    // 触屏设备点击视角区会合成 mouse 事件导致误开火，射击一律走 FIRE 按钮
    this._isTouchDevice = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    this._onCanvasClick = () => {
      if (this._isTouchDevice) return;
      if (this.state === 'menu' || this.state === 'over') return;
      if (document.pointerLockElement !== this.renderer.domElement) {
        this._requestLock();
        return;
      }
      if (this.state === 'playing') {
        this.weapons.triggerSemi();
      }
    };
    this.renderer.domElement.addEventListener('mousedown', this._onCanvasClick);

    // 触屏视角控制（document 级，多指支持，独立于 FIRE/D-pad）
    this._lookTouchId = null;
    this._lookLastX = 0;
    this._lookLastY = 0;

    this._onDocTouchStart = (e) => {
      if (this.state !== 'playing') return;
      // 遍历新增的触点，找到一个不在控件上的 → 作为视角触点
      for (const t of e.changedTouches) {
        // 跳过控件区域（D-pad、FIRE、动作键、小地图、overlay）
        if (t.target.closest && t.target.closest('#touchControls, #minimapWrap, .overlay, #menu, #result, #pause, #topbar')) continue;
        if (this._lookTouchId === null) {
          this._lookTouchId = t.identifier;
          this._lookLastX = t.clientX;
          this._lookLastY = t.clientY;
        }
      }
    };
    this._onDocTouchMove = (e) => {
      if (this.state !== 'playing' || this._lookTouchId === null) return;
      e.preventDefault();
      for (const t of e.changedTouches) {
        if (t.identifier === this._lookTouchId) {
          const dx = t.clientX - this._lookLastX;
          const dy = t.clientY - this._lookLastY;
          this._lookLastX = t.clientX;
          this._lookLastY = t.clientY;
          this.player.onTouchLook(dx, dy);
        }
      }
    };
    this._onDocTouchEnd = (e) => {
      for (const t of e.changedTouches) {
        if (t.identifier === this._lookTouchId) {
          this._lookTouchId = null;
        }
      }
    };
    document.addEventListener('touchstart', this._onDocTouchStart, { passive: false });
    document.addEventListener('touchmove', this._onDocTouchMove, { passive: false });
    document.addEventListener('touchend', this._onDocTouchEnd, { passive: false });
    document.addEventListener('touchcancel', this._onDocTouchEnd, { passive: false });

    // 移动端虚拟按钮（D-pad + 动作键）→ 模拟键盘事件
    this._setupVirtualControls();

    // Esc 暂停（pointerlock 退出会自动触发，这里处理继续）
    this._onKeyDown = (e) => {
      if (e.code === 'Escape') {
        if (this.state === 'playing') {
          document.exitPointerLock();
        }
      }
    };
    window.addEventListener('keydown', this._onKeyDown);

    // 点击暂停界面任意处 → 重新锁定
    this.hud.pause.addEventListener('click', () => this._resume());
  }

  _setupVirtualControls() {
    const touchControls = document.getElementById('touchControls');
    const isTouchDevice = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    const isSmallScreen = window.innerWidth <= 1024;
    const forceShow = window.location.search.includes('controls=1') || window.location.search.includes('mobile=1');
    if (!touchControls) return;
    // 触屏设备 OR 小屏 OR URL 强制：进入游戏中时显示虚拟控制
    if (!isTouchDevice && !isSmallScreen && !forceShow) return;
    const origShow = this.hud.show.bind(this.hud);
    this.hud.show = () => { origShow(); touchControls.classList.remove('hidden'); };
    const origHide = this.hud.hide.bind(this.hud);
    this.hud.hide = () => { origHide(); touchControls.classList.add('hidden'); };

    // 触屏设备上浏览器会在 touch 后合成 mouse 事件，若同时绑定会导致按钮双触发，
    // 因此触屏只绑 touch 系列，鼠标设备只绑 mouse 系列
    const bindPress = (btn, press, release) => {
      btn.addEventListener('touchstart', press, { passive: false });
      btn.addEventListener('touchend', release, { passive: false });
      btn.addEventListener('touchcancel', release, { passive: false });
      if (!isTouchDevice) {
        btn.addEventListener('mousedown', press);
        btn.addEventListener('mouseup', release);
        btn.addEventListener('mouseleave', release);
      }
    };

    // D-pad / 动作键 → 模拟键盘
    const fireKey = (code, down) => {
      this.player.keys[code] = down;
      if (down && code === 'KeyR') this.weapons.startReload();
    };
    touchControls.querySelectorAll('[data-key]').forEach(btn => {
      const code = btn.dataset.key;
      const press = (e) => { e.preventDefault(); btn.classList.add('active'); fireKey(code, true); };
      const release = (e) => { e.preventDefault(); btn.classList.remove('active'); fireKey(code, false); };
      bindPress(btn, press, release);
    });

    // FIRE 按钮：按下触发半自动 + 标记自动射击；松开停止自动
    touchControls.querySelectorAll('[data-action="fire"]').forEach(btn => {
      const press = (e) => {
        e.preventDefault(); btn.classList.add('active');
        this.weapons.triggerSemi();   // 半自动：每次按下触发一次
        this.weapons.setFiring(true); // 自动：持续射击标记
      };
      const release = (e) => {
        e.preventDefault(); btn.classList.remove('active');
        this.weapons.setFiring(false);
      };
      bindPress(btn, press, release);
    });

    // 武器切换按钮
    touchControls.querySelectorAll('[data-action="weapon"]').forEach(btn => {
      const tap = (e) => {
        e.preventDefault(); btn.classList.add('active');
        const slot = parseInt(btn.dataset.slot);
        this.weapons.switchTo(slot === 1 ? 'usp' : 'ak47');
        setTimeout(() => btn.classList.remove('active'), 200);
      };
      const noop = () => {};
      bindPress(btn, tap, noop);
    });

    // 暂停按钮
    touchControls.querySelectorAll('[data-action="pause"]').forEach(btn => {
      const tap = (e) => {
        e.preventDefault(); btn.classList.add('active');
        if (this.state === 'playing') {
          this.state = 'paused';
          this.hud.showPause();
        }
        setTimeout(() => btn.classList.remove('active'), 200);
      };
      const noop = () => {};
      bindPress(btn, tap, noop);
    });
  }

  _requestLock() {
    try {
      const el = this.renderer.domElement;
      if (!el.requestPointerLock) return;
      const p = el.requestPointerLock();
      if (p && typeof p.catch === 'function') p.catch(() => {});
    } catch (e) { /* PointerLock 不可用（移动端/iframe），忽略 */ }
  }

  _resume() {
    if (this.state !== 'paused') return;
    this.hud.hidePause();
    this.state = 'playing';
    // PC 端尝试重新锁定鼠标；移动端无 PointerLock 则直接继续
    this._requestLock();
  }

  _bindResize() {
    // 横竖屏检测 + 渲染尺寸同步
    const onResize = () => {
      const portrait = window.innerHeight > window.innerWidth;
      document.body.classList.toggle('portrait', portrait);
      document.body.classList.toggle('landscape', !portrait);
      // 竖屏水平视野窄，用更大的垂直 FOV 补偿
      this.camera.fov = portrait ? CONFIG.fovPortrait : CONFIG.fov;
      this.camera.aspect = window.innerWidth / window.innerHeight;
      this.camera.updateProjectionMatrix();
      this.renderer.setSize(window.innerWidth, window.innerHeight);
    };
    window.addEventListener('resize', onResize);
    // orientationchange 后需等浏览器完成布局再读尺寸
    window.addEventListener('orientationchange', () => setTimeout(onResize, 120));
    onResize();   // 初始化
  }

  // ---------- 一局开始 ----------
  _beginRun() {
    this.audio.init();      // 用户手势内初始化音频
    this.hud.hideMenu();
    this.hud.hideResult();
    this.hud.hidePause();
    this.hud.show();

    // 重置玩家与武器
    this.player.reset(this.gameMap.spawns.player);
    this.weapons.reset();
    this.pickups.reset();
    this.hud.updateVitals(this.player.health, this.player.armor);
    this.hud.updateWeapon(CONFIG.weapons.usp, this.weapons.state);

    // 清掉旧敌人
    for (const en of this.enemies) en.dispose();
    this.enemies.length = 0;

    this.wave = 0;
    this.kills = 0;
    this.totalKills = 0;
    this.startTime = performance.now();
    this.state = 'playing';
    this._nextWave();

    this._requestLock();
  }

  _nextWave() {
    this.wave++;
    if (this.wave > CONFIG.waves.length) {
      this._endRun(true);
      return;
    }
    const def = CONFIG.waves[this.wave - 1];
    this.hud.toast(`回合 ${this.wave}：${def.count} 名敌人`);
    this.audio.wave(this.wave);

    // 生成敌人队列（从出生点随机分配）
    const names = ['Phantom', 'Viper', 'Ghost', 'Reaper', 'Fang', 'Echo', 'Talon', 'Raven'];
    this.spawnQueue = [];
    for (let i = 0; i < def.count; i++) {
      const spawn = this.gameMap.spawns.enemy[i % this.gameMap.spawns.enemy.length];
      this.spawnQueue.push({
        pos: spawn.clone().add(new THREE.Vector3(
          (Math.random() - 0.5) * 4, 0, (Math.random() - 0.5) * 4
        )),
        hp: def.hp,
        speed: def.speed,
        name: names[Math.floor(Math.random() * names.length)],
      });
    }
    // 立即刷出前 2 个，其余间隔刷
    this._spawnFromQueue(2);
    this.spawnTimer = 2.5;
    this._refreshScore();
  }

  _spawnFromQueue(n) {
    for (let i = 0; i < n && this.spawnQueue.length > 0; i++) {
      const spec = this.spawnQueue.shift();
      const en = new Enemy(this.scene, this.gameMap, this.player, this.hud, {
        hp: spec.hp, speed: spec.speed, name: spec.name,
      });
      en.spawnAt(spec.pos);
      this.enemies.push(en);
    }
    this._refreshScore();
  }

  _refreshScore() {
    const alive = this.enemies.filter(e => e.alive).length + this.spawnQueue.length;
    this.hud.updateScore(alive, this.kills, this.wave);
  }

  // ---------- 主循环 ----------
  _loop() {
    requestAnimationFrame(() => this._loop());
    const now = performance.now();
    let dt = (now - this._lastTime) / 1000;
    this._lastTime = now;
    // 钳制 dt 防止切后台后大跳
    dt = Math.min(dt, 0.05);

    this._update(dt);
    this.renderer.render(this.scene, this.camera);
    this.hud.drawMinimap();
  }

  _update(dt) {
    if (this.state !== 'playing') return;

    // 玩家
    this.player.update(dt);
    // 武器
    this.weapons.update(dt);
    // 血包
    this.pickups.update(dt);

    // 敌人
    for (const en of this.enemies) en.update(dt);
    // 清理完全消失的敌人
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const en = this.enemies[i];
      if (!en.alive && !en.mesh.visible) {
        en.dispose();
        this.enemies.splice(i, 1);
      }
    }

    // 统计本帧击杀（对比上一帧血量总和简化处理 → 改用回调已在 weapon 内累加 kills）
    // 这里仅刷新计数
    this._refreshScore();

    // 间隔刷怪
    if (this.spawnQueue.length > 0) {
      this.spawnTimer -= dt;
      if (this.spawnTimer <= 0) {
        // 场上存活敌人少于阈值就再刷
        const aliveCount = this.enemies.filter(e => e.alive).length;
        if (aliveCount < 4) {
          this._spawnFromQueue(1);
          this.spawnTimer = 2.5;
        } else {
          this.spawnTimer = 1.0;
        }
      }
    }

    // 回合完成判定
    const aliveCount = this.enemies.filter(e => e.alive).length;
    if (this.spawnQueue.length === 0 && aliveCount === 0) {
      // 进入下一波（短暂延迟）
      this._waveCooldown = (this._waveCooldown ?? 0) + dt;
      if (this._waveCooldown > 2.0) {
        this._waveCooldown = 0;
        this._nextWave();
      }
    } else {
      this._waveCooldown = 0;
    }

    // 玩家死亡
    if (!this.player.alive) {
      this._endRun(false);
    }
  }

  _endRun(win) {
    this.state = 'over';
    document.exitPointerLock?.();
    this.hud.hideClickHint();
    const time = ((performance.now() - this.startTime) / 1000) | 0;
    const mm = String((time / 60) | 0).padStart(2, '0');
    const ss = String(time % 60).padStart(2, '0');
    // 用回调累加的 totalKills（敌人倒地动画结束后会从数组移除，不能靠遍历统计）
    const totalKills = this.totalKills || 0;
    if (win) this.audio.win(); else this.audio.lose();
    this.hud.showResult(win, {
      '通关回合': win ? `${CONFIG.waves.length} / ${CONFIG.waves.length}` : `${this.wave - 1} / ${CONFIG.waves.length}`,
      '累计击杀': totalKills,
      '存活时间': `${mm}:${ss}`,
    });
  }
}

// 给 weapon 的 killFeed 回调累加 kills —— 通过监听 HUD 的事件过于复杂，
// 这里在 weapon 内部已调用 hud.killFeed；我们在 HUD 上挂个回调计数。
// 简化：重写 killFeed 包一层
const origKillFeed = HUD.prototype.killFeed;
HUD.prototype.killFeed = function (name) {
  origKillFeed.call(this, name);
  if (this._onKill) this._onKill();
};

// 启动
window.addEventListener('DOMContentLoaded', () => {
  const game = new Game();
  // 把击杀计入统计
  game.hud._onKill = () => {
    game.kills++;
    game.totalKills++;
  };
  window.__game = game;   // 调试用
});
